// Events related list on a club group. Same rows as the Events tab.
import React, { useCallback, useState } from 'react';
import { View } from 'react-native';
import { router, useFocusEffect } from 'expo-router';
import { EventRow, eventEndMs, useEventListLayout } from './events';
import { Button, EmptyState, ErrorText, ListView } from './ui';
import { eventInMemberDirectory } from '../lib/event-visibility';
import { EVENTS_PAST_DAYS, listEvents } from '../lib/api';
import { useSession } from '../lib/session';
import type { ClubEvent } from '../lib/types';

export function GroupEvents({ groupId, mod }: { groupId: string; mod: boolean }) {
  const { userId } = useSession();
  const [rows, setRows] = useState<ClubEvent[] | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const { columns, onLayout } = useEventListLayout();
  const load = useCallback(() => {
    listEvents(mod).then((events) => {
      setRows(events.filter((event) => event.group_id === groupId && eventInMemberDirectory(event, { moderator: mod, userId, attendingIds: new Set() })));
      setErr(null);
    }).catch((e: { message?: string }) => setErr(e.message ?? 'Couldn’t load events.'));
  }, [groupId, mod, userId]);
  useFocusEffect(useCallback(() => { load(); }, [load]));
  const openNew = () => router.push(`/events/manage/new?group=${groupId}`);
  return (
    <View onLayout={onLayout}>
      <ErrorText>{err}</ErrorText>
      <ListView title="Events" note={`Upcoming, and the last ${EVENTS_PAST_DAYS} days.`}
        count={rows?.length} columns={columns} loading={!rows && !err}
        empty={<EmptyState icon="calendar-outline" title="No events" body="Events in this group show up here."
          action={mod ? <Button small icon="add" title="New event" onPress={openNew} /> : undefined} />}
        footer={mod && rows && rows.length > 0 ? (
          <View style={{ paddingHorizontal: 16, paddingVertical: 12 }}>
            <Button small icon="add" title="New event" onPress={openNew} />
          </View>
        ) : null}>
        {rows?.map((event) => (
          <EventRow key={event.id} e={event} past={eventEndMs(event) <= Date.now()} mod={mod} columns={columns} />
        ))}
      </ListView>
    </View>
  );
}
