// Group record page. Same shape as an event: highlight, publish, related lists, about.
// No Meetup member count. People count only when they join the app, and that list is not here yet.
import { useCallback, useState } from 'react';
import { ActivityIndicator, Linking, Text, View } from 'react-native';
import { Redirect, router, Stack, useFocusEffect, useLocalSearchParams } from 'expo-router';
import { GroupEvents } from '../../../components/group-events';
import { GroupSponsors } from '../../../components/group-sponsors';
import { GroupPublishList } from '../../../components/group-publish';
import { useConfirmDelete } from '../../../components/confirm-sheet';
import { DeleteGroupSheet } from '../../../components/delete-group-sheet';
import { ActionRow, CoverBand, EntityTitle } from '../../../components/record-chrome';
import { BackChevron, Button, EmptyState, ErrorText, FieldGrid, Page, SectionCard, StatusPill, styles } from '../../../components/ui';
import { RichText } from '../../../components/rich-text';
import { rememberReturnPath } from '../../../lib/auth';
import { deleteGroup, getGroup } from '../../../lib/groups';
import { safeMeetupUrl } from '../../../lib/publications';
import { flash } from '../../../lib/flash';
import { OwnerFace } from '../../../components/owner-face';
import { useOwnerProfile } from '../../../lib/owner-label';
import { useSession } from '../../../lib/session';
import { colors } from '../../../lib/theme';
import type { ClubGroup } from '../../../lib/types';

export default function GroupPage() {
  const raw = useLocalSearchParams<{ id: string }>().id;
  const id = Array.isArray(raw) ? raw[0] : raw;
  const { userId, isModerator, demo, loading } = useSession();
  const mod = isModerator && !demo && !!userId;
  const [group, setGroup] = useState<ClubGroup | null | undefined>(undefined);
  const [err, setErr] = useState<string | null>(null);
  const removeSheet = useConfirmDelete();
  const owner = useOwnerProfile(group?.owner_id, mod);
  const load = useCallback(() => {
    if (!userId || !id) return;
    getGroup(id).then(setGroup).catch((e) => setErr(e.message));
  }, [userId, id]);
  useFocusEffect(useCallback(() => { load(); }, [load]));

  const remove = () => {
    if (!id) return;
    removeSheet.run(async () => {
      await deleteGroup(id);
      flash('Group deleted');
      router.replace('/groups');
    });
  };

  if (loading) return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
  if (!userId) {
    const next = id ? `/groups/${id}` : null;
    if (next) rememberReturnPath(next);
    return <Redirect href={next ? `/sign-in?next=${encodeURIComponent(next)}` : '/sign-in'} />;
  }
  if (group === undefined && !err) return (
    <Page scroll={false} fill>
      <BackChevron fallback="/groups" />
      <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>
    </Page>
  );
  if (group === undefined || group === null) return (
    <Page>
      <BackChevron fallback="/groups" />
      {group === undefined ? <ErrorText>{err}</ErrorText>
        : <EmptyState icon="people-outline" title="Group not found" body="It may have been removed."
          action={<Button small variant="neutral" title="All groups" onPress={() => router.replace('/groups')} />} />}
    </Page>
  );

  const meetup = safeMeetupUrl(group.meetup_url);
  const recordFields: [string, React.ReactNode][] = [
    ['City', group.locality ?? '—'],
    ['Web address', group.slug],
    ...(owner ? [['Owner', <OwnerFace profile={owner} />] as [string, React.ReactNode]] : []),
  ];
  return (
    <Page>
      <Stack.Screen options={{ title: group.name, headerShown: false }} />
      <BackChevron fallback="/groups" />
      <CoverBand url={group.image_url} />
      <EntityTitle title={group.name} meta={group.locality} pills={<StatusPill label={group.archived ? 'Archived' : 'Active'} tone={group.archived ? 'default' : 'success'} />} />
      {mod ? <ActionRow>
        <Button small variant="neutral" icon="create-outline" title="Edit" onPress={() => router.push(`/groups/manage/${group.id}`)} />
        <Button small variant="neutral" icon="bar-chart-outline" title="Analytics" onPress={() => router.push(`/groups/${group.id}/analytics`)} />
        <Button small variant="danger" icon="trash-outline" title="Delete" onPress={removeSheet.ask} />
      </ActionRow> : null}
      <FieldGrid fields={recordFields} />
      <ErrorText>{err}</ErrorText>
      {mod ? <GroupPublishList group={group} /> : null}
      <SectionCard title="Details">
        <FieldGrid fields={[
          ['City', group.locality ?? '—'],
          ['Web address', group.slug],
          ['Meetup', meetup
            ? <Text style={styles.link} onPress={() => Linking.openURL(meetup)}>{meetup}</Text>
            : '—'],
        ]} />
      </SectionCard>
      <GroupEvents groupId={group.id} mod={mod} />
      {mod ? <GroupSponsors groupId={group.id} /> : null}
      {group.description ? <SectionCard title="About"><RichText source={group.description} /></SectionCard> : null}
      <DeleteGroupSheet visible={removeSheet.open} busy={removeSheet.busy} error={removeSheet.error}
        onCancel={removeSheet.cancel}
        onConfirm={remove} />
    </Page>
  );
}
